function padic_val_int(p, n):
    if n == 0: return +infinity
    n <- |n|; k <- 0
    while n mod p == 0:
        n <- n / p; k <- k + 1
    return k

function padic_val_rat(p, a/b):
    if a/b == 0: return +infinity
    return padic_val_int(p, a) - padic_val_int(p, b)

