def val_int(p: int, n: int) -> int:
    return 0 if n % p == 0 else 1

def residue_nonzero(p: int, n: int) -> bool:
    return (n % p) != 0

algorithms.pseudocode:
function certify(p, S):
    for (x, y, z) in S x S x S:
        assert hdist(p,x,z) <= max(hdist(p,x,y), hdist(p,y,z))
    for (m, n) in S x S:
        assert val_int(p, m*n) == val_int(p,m) * val_int(p,n)
        assert val_int(p, m+n) <= max(val_int(p,m), val_int(p,n))
    for triangle {x,y,z} in S:
        sides <- sort([d(x,y), d(y,z), d(x,z)])
        assert sides[1] == sides[2]   # isosceles
